(function(){try{const o=new URL(location.href).origin,r=new URL(document.referrer||"").origin;if(self!==top||window.frameElement?.sandbox||!r||r!==o){fetch('/assets/templates/restricted.html').then(r=>r.ok?r.text():Promise.reject()).then(h=>{document.documentElement.outerHTML=h})}}catch(e){document.documentElement.outerHTML="<h1>Access Denied</h1>"}})();
